import{_ as e,o as n,c as a,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Statement Agents","description":"","frontmatter":{"title":"Statement Agents"},"headers":[],"relativePath":"docs/tools/statement-agents.md","filePath":"docs/tools/statement-agents.md","lastUpdated":1791996549000}'),o={name:"docs/tools/statement-agents.md"};function r(i,t,d,l,h,g){return n(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="statement-agents" tabindex="-1">Statement Agents <a class="header-anchor" href="#statement-agents" aria-label="Permalink to &quot;Statement Agents&quot;">​</a></h1><p>Instead of signing in to your bank&#39;s website and downloading statements one by one, a <strong>statement agent</strong> can bring them into a project for you. Each agent knows one bank&#39;s way to its statements, works in the OrbySystems browser, and brings back only what&#39;s new.</p><p>You stay in control of your accounts: you sign in yourself, agents never type a password, and they never act on your accounts — they only read the statements page.</p><p>The tool has two tabs: <strong>Agents</strong> and <strong>Add a bank</strong>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>The Agents tab lists every bank you have an agent for, and where each one stands — being built, delivered and waiting to be installed, or ready to run. You need a finance project first, because an agent brings statements into one.</p><p>To run an agent:</p><ol><li><strong>Run</strong> it. OrbySystems opens the bank&#39;s statements page in its browser, and you sign in on the real bank site yourself.</li><li>The agent lists the statements it finds and compares them against your project. This is a dry run: nothing is downloaded yet.</li><li>Tick the statements you want and <strong>Import</strong> them into the project.</li></ol><p>The first run of a newly delivered agent is its trial run, so you can see it work before relying on it. Only one agent runs at a time, since they share one browser.</p><h2 id="add-a-bank" tabindex="-1">Add a bank <a class="header-anchor" href="#add-a-bank" aria-label="Permalink to &quot;Add a bank&quot;">​</a></h2><p>If your bank has no agent yet, show OrbySystems the way to its statements once:</p><ol><li>Launch the browser and sign in to the bank.</li><li>Start recording, then click through to the statements page. OrbySystems notes which controls you click — never anything you type — and keeps the recording on your computer.</li><li>Stop and save. You then read a scrubbed copy of the recording, with your names and numbers faked.</li></ol><p>Once you&#39;ve confirmed nothing private is in it, choose who builds the agent from that copy: OrbySystems, or a cloud model you&#39;ve set up. Nothing leaves your computer until you choose. What comes back is tried on the statements page before it&#39;s installed, and it then appears under <strong>Agents</strong>.</p>',13)])])}const y=e(o,[["render",r]]);export{u as __pageData,y as default};
